205	      rec.before = baseResults[fault.id];
206	
207	      // Observe: read a failing trial back from neatlogs. Oldest trace first: the previous run's on
208	      // the same code (minutes old), then this run's BEFORE scorecard (it ran earliest), then the
209	      // Judge's baseline; if no sampled trial failed, one failing seed is replayed traced.
210	      const candidates: ObserveCandidate[] = [
211	        ...(previous[fault.id] ?? []).map((e) => ({ seed: e.seed, traceId: e.traceId, source: 'previous' as const })),
212	        ...before[fault.id].examples.map((e) => ({ seed: e.seed, traceId: e.traceId, source: 'before' as const })),
213	        ...baseResults[fault.id].examples.map((e) => ({ seed: e.seed, traceId: e.traceId, source: 'judge' as const })),
214	      ];
215	      const observed = await observeFailure({
216	        fault: fault.id,
217	        candidates,
218	        waitMs: readbackWaitMs,
219	        cache: readCache,
220	        rerun: async (seed) => {
221	          const obs = await phase(`observe: replay failing ${fault.id} trial (seed ${seed})`, { fault: fault.id, seed }, () =>
222	            runTrial({ target: original, fault, seed, brain: o.brain, deadlineMs: o.deadlineMs, maxSteps: o.maxSteps, traced: true }),
223	          );
224	          await flush().catch(() => false);
225	          return obs.traceId;
226	        },
227	      });
228	      rec.observe = observed.record;
229	      emit({ type: 'observe', ...observed.record });
230	      // Entire Graph fix-site search for this fault, limited to the target's own files.
231	      const graphHints = graph?.search(fault.hypothesis, 3, targetRel) ?? undefined;
232	
233	      const failed: FailedAttempt[] = [];
234	      const slo = sloPlans.find((p) => p.fault === fault.id);
235	      for (let round = 1; round <= o.maxAttempts; round++) {
236	        const cp = checkpoints.save(`before ${fault.id} ${entrants ? 'round' : 'attempt'} ${round}`, baseFiles, { fault: fault.id, attempt: round });
237	        emit({ type: 'checkpoint', action: 'save', id: cp.id, label: cp.label });
238	
239	        const ctx = { target: original.name, fault, findings: rec.findings, files: baseFiles, before: baseResults[fault.id], failed, rules, preferred: o.memory ? memory.ranked(fault.kind) : [], neatlogsEvidence: observed.evidence, graphHints };
240	        const entries: Entry[] = await phase(`3 blue: propose fix for ${fault.id} #${round}`, { fault: fault.id, attempt: round, ...(entrants ? { tournament: true } : {}) }, async () =>
241	          entrants ? proposeAll(entrants, ctx) : [{ entrant: fixer.name, proposal: await fixer.propose(ctx) }],
242	        );
243	        if (!entries.some((e) => e.proposal)) {
244	          emit({ type: 'log', message: `Blue has no further strategies for ${fault.id}${entrants ? ` (${entries.map((e) => `${e.entrant}: ${e.error}`).join('; ')})` : ''}` });
245	          break;
246	        }
247	
248	        // The Judge verifies every candidate one at a time, so latency measurements don't compete for the CPU.
249	        const candidates: { entry: Entry; v?: Verdict; diffSize: number; n?: number }[] = [];
250	        for (const entry of entries) {
251	          const proposal = entry.proposal;
252	          if (!proposal) {
253	            candidates.push({ entry, diffSize: 0 });
254	            continue;
255	          }
256	          attempts++;
257	          const n = rec.attempts.length + 1;
258	          const diff = diffFiles(baseFiles, proposal.files, `${targetRel}/`);
259	          const stats = diffStats(diff);
260	          emit({ type: 'attempt', fault: fault.id, n, strategy: proposal.strategy, title: proposal.title, rationale: proposal.rationale, author: proposal.author, diff, ...stats, ...(entrants ? { round } : {}) });
261	
262	          const candidateDir = ws.materialize(`${fault.id}-a${n}`, proposal.files);
263	          const v = await phase(`4 judge: verify ${fault.id} #${n}`, { fault: fault.id, attempt: n, strategy: proposal.strategy }, () =>
264	            judge({ fault, candidate: () => loadTarget(candidateDir), baseResults, opts: judgeOpts, slo, budgets: o.budgets }),
265	          );
266	          emit({
267	            type: 'verdict', fault: fault.id, n, status: v.status, reasons: v.reasons, pValue: v.pValue, afterPassed: v.after.passed, trials: v.after.trials, regressions: v.regressions,
268	            ...(v.slo ? { slo: v.slo } : {}), ...(v.overhead ? { overhead: v.overhead } : {}), ...(entrants ? { author: proposal.author, round } : {}),
269	          });
270	          rec.attempts.push({
271	            n,
272	            strategy: proposal.strategy,
273	            title: proposal.title,
274	            rationale: proposal.rationale,
275	            author: proposal.author,
276	            diff,
277	            checkpoint: cp.id,
278	            verdict: { status: v.status, reasons: v.reasons, pValue: v.pValue, afterPassed: v.after.passed, trials: v.after.trials, ...(v.slo ? { slo: v.slo } : {}), ...(v.overhead ? { overhead: v.overhead } : {}) },
279	          });
280	          memory.record(fault.kind, proposal.strategy, v.status === 'fixed');
281	          candidates.push({ entry, v, diffSize: stats.added + stats.removed, n });
282	        }
283	
284	        let chosen = candidates.find((c) => c.v?.status === 'fixed');
285	        if (entrants) {
286	          const { ranking, winner } = rankContenders(
287	            candidates.map((c) => ({
288	              entrant: c.entry.entrant,
289	              status: c.v?.status ?? 'no-proposal',
290	              strategy: c.entry.proposal?.strategy,
291	              title: c.entry.proposal?.title,
292	              ...(c.v?.slo ? { sloDemonstrated: c.v.slo.demonstrated } : {}),
293	              ...(c.v?.overhead ? { overhead: c.v.overhead } : {}),
294	              diffSize: c.diffSize,
295	              summary: c.v?.reasons[0] ?? c.entry.error,
296	            })),
297	          );
298	          const t: TournamentResult = { fault: fault.id, round, entrants: entries.map((e) => e.entrant), ranking, ...(winner ? { winner } : {}) };
299	          (rec.tournament ??= []).push(t);
300	          for (const r of ranking) {
301	            const c = candidates.find((x) => x.entry.entrant === r.entrant);
302	            const a = c?.n !== undefined ? rec.attempts.find((x) => x.n === c.n) : undefined;
303	            if (a) a.tournament = { round, rank: r.rank, outcome: r.outcome, reason: r.reason };
304	          }
305	          emit({ type: 'tournament', ...t });
306	          chosen = winner ? candidates.find((c) => c.entry.entrant === winner) : undefined;
307	        }
308	
309	        if (chosen?.v && chosen.entry.proposal) {
310	          const proposal = chosen.entry.proposal;
311	          const v = chosen.v;
312	          // Guard: ship a regression test and prove it fails without the fix.
313	          const spec: ChaosSpec = { fault: fault.id, trials: o.judgeTrials, seed: o.seed + 2_000_003, strategy: proposal.strategy, createdBy: 'bulwark' };
314	          const fixedFiles = withSpec(proposal.files, spec);
315	          const fixedDir = ws.materialize(`${fault.id}-accepted`, fixedFiles);
316	          const fixedTarget = await loadTarget(fixedDir);
317	          const m = await phase(`5 guard: prove regression test for ${fault.id}`, { fault: fault.id }, () =>
318	            mutationCheck(spec, baseTarget, fixedTarget, judgeOpts),
319	          );
320	          rec.mutation = { ok: m.ok, unfixedPassed: m.unfixed.passed, fixedPassed: m.fixed.passed, trials: spec.trials };
321	          emit({ type: 'mutation', fault: fault.id, ...rec.mutation });
322	
323	          baseFiles = fixedFiles;
324	          baseDir = fixedDir;
325	          baseTarget = fixedTarget;
326	          baseResults = v.results;
327	          rec.status = 'fixed';
328	          break;
329	        }
330	
331	        for (const c of candidates) {
332	          if (c.entry.proposal && c.v) failed.push({ strategy: c.entry.proposal.strategy, author: c.entry.proposal.author, rationale: c.entry.proposal.rationale, reasons: c.v.reasons });
333	        }
334	        baseFiles = checkpoints.restore(cp.id);
335	        rollbacks++;
336	        emit({ type: 'checkpoint', action: 'restore', id: cp.id, label: cp.label });
337	      }
338	      emit({ type: 'fault-done', fault: fault.id, status: rec.status, attempts: rec.attempts.length });
339	    }
340	
341	    // Red re-runs its original attack, same seeds, against the final code.
342	    const after = await phase('6 red: attack scorecard AFTER', { phase: 'after', trials: o.redTrials, seed: o.seed }, () => runAll(baseTarget, redOpts));
343	    // ws: the workspace holding the final code, so the dashboard can replay "after" trials against it.
344	    emit({ type: 'scorecard', phase: 'after', results: Object.values(after), overall: overallPassRate(after), ...(baseDir !== o.targetDir ? { ws: basename(baseDir) } : {}) });
345	    const residual = analyzeTarget(baseDir, baseTarget);
346	    emit({ type: 'residual', findings: residual });
347	    // One last look at neatlogs traces that weren't finalized when Blue needed them, for the postmortems.
348	    const late = await recheckPending(records.map((r) => r.observe), { cache: readCache });
349	    if (records.some((r) => r.observe?.traceId)) {
350	      const read = records.filter((r) => r.observe?.status === 'read').length;
351	      emit({ type: 'log', message: `neatlogs read-back: ${read}/${records.filter((r) => r.observe).length} failing-trial traces read${late ? ` (${late} only at the end of the run)` : ''}` });
352	    }
353	
354	    const book = await loadPriceBook({ provider: llmProvider(), cachePath: join(o.stateDir, 'pricing-0g.json') });
355	    const cost = meter.summarize(book.priceFor, `0G router prices (${book.zgSource}); Anthropic-direct static table`);
356	
357	    // Artifacts.
358	    mkdirSync(dir, { recursive: true });
359	    const patch = diffFiles(originalFiles, baseFiles, `${targetRel}/`);
360	    const traces = process.env.NEATLOGS_API_KEY ? 'exported to neatlogs (workflow "bulwark")' : 'local only (set NEATLOGS_API_KEY to export)';
361	    const artifacts = {
362	      patch: join(dir, 'fix.patch'),
363	      pr: join(dir, 'PR.md'),
364	      badge: join(dir, 'badge.svg'),
365	      postmortems: records.map((r) => join(dir, `postmortem-${r.fault}.md`)),
366	    };
367	    writeFileSync(artifacts.patch, patch);
368	    writeFileSync(artifacts.pr, prBody({ target: original.name, runId, records, before, after, diff: patch, traces, residual, provenance, cost }));
369	    writeFileSync(artifacts.badge, badgeSvg(overallPassRate(after)));
370	    records.forEach((r, i) => writeFileSync(artifacts.postmortems[i], postmortem(r, runId)));
371	    const meta = { run: runId, trials: o.redTrials, seed: o.seed };
372	    writeFileSync(join(dir, 'scorecard-before.md'), renderMarkdown(original, Object.values(before), meta));
373	    writeFileSync(join(dir, 'scorecard-after.md'), renderMarkdown(original, Object.values(after), meta));
374	    copyFileSync(artifacts.badge, join(o.stateDir, 'badge.svg'));
375	    if (o.memory) memory.save();
376	
377	    const summary: LoopSummary = {
378	      runId,
379	      dir,
380	      target: original.name,
381	      fixer: fixer.name,
382	      overallBefore: overallPassRate(before),
383	      overallAfter: overallPassRate(after),
384	      fixed: records.filter((r) => r.status === 'fixed').map((r) => r.fault),
385	      unfixed: records.filter((r) => r.status === 'unfixed').map((r) => r.fault),
386	      skipped: records.filter((r) => r.status === 'skipped').map((r) => r.fault),
387	      attempts,
388	      rollbacks,
389	      residual,
390	      artifacts,
391	      finalFiles: baseFiles,
392	      targetRel,
393	      cost,
394	    };
395	    writeFileSync(join(dir, 'summary.json'), JSON.stringify({ ...summary, targetHash, records, before, after }, null, 2));
396	    writeFileSync(join(o.stateDir, 'latest.json'), JSON.stringify({ runId, dir }, null, 2));
397	    emit({ type: 'run-done', summary });
398	    return summary;
399	  });
400	}
