402	/** Content hash of the target's editable files, so a later run knows whether a past trace shows the same code. */
403	export function hashFiles(files: Files): string {
404	  const h = createHash('sha256');
405	  for (const path of Object.keys(files).sort()) h.update(`${path}\0${files[path]}\0`);
406	  return h.digest('hex').slice(0, 16);
407	}
