409	/** The previous run's traced failing trials per fault, when it attacked exactly this code. */
410	export function previousFailures(stateDir: string, targetHash: string): Record<string, { seed: number; traceId: string }[]> {
411	  try {
412	    const { dir } = JSON.parse(readFileSync(join(stateDir, 'latest.json'), 'utf8')) as { dir: string };
413	    const prev = JSON.parse(readFileSync(join(dir, 'summary.json'), 'utf8')) as { targetHash?: string; before?: Record<string, ExperimentResult> };
414	    if (prev.targetHash !== targetHash || !prev.before) return {};
415	    return Object.fromEntries(
416	      Object.entries(prev.before).map(([fault, r]) => [fault, r.examples.flatMap((e) => (e.traceId ? [{ seed: e.seed, traceId: e.traceId }] : []))]),
417	    );
418	  } catch {
419	    return {};
420	  }
421	}
