423	function git(args: string[], cwd?: string): string {
424	  const res = spawnSync('git', args, { cwd, encoding: 'utf8' });
425	  if (res.status !== 0) throw new Error(`git ${args.join(' ')} failed: ${res.stderr.trim()}`);
426	  return res.stdout.trim();
427	}
