429	/** Commits the verified fixes to a new branch via a throwaway worktree; the current checkout is untouched. */
430	export function applyAsBranch(summary: LoopSummary, stateDir = '.bulwark'): string {
431	  const branch = `bulwark/fix-${summary.runId}`;
432	  const wt = resolve(stateDir, 'worktrees', summary.runId);
433	  git(['worktree', 'add', '-q', '-b', branch, wt, 'HEAD']);
434	  try {
435	    for (const [path, content] of Object.entries(summary.finalFiles)) {
436	      const dest = join(wt, summary.targetRel, path);
437	      mkdirSync(join(dest, '..'), { recursive: true });
438	      writeFileSync(dest, content);
439	    }
440	    git(['add', '-A'], wt);
441	    git(['commit', '-q', '-m', `Bulwark: verified resilience fixes for ${summary.target}\n\nFixed: ${summary.fixed.join(', ') || 'none'}\nRun: ${summary.runId}`], wt);
442	  } finally {
443	    git(['worktree', 'remove', '--force', wt]);
444	  }
445	  return branch;
446	}
