448	/** Pushes the branch and opens a PR with the Bulwark report as its body. */
449	export function openPullRequest(branch: string, summary: LoopSummary): string {
450	  git(['push', '-u', 'origin', branch]);
451	  const res = spawnSync('gh', ['pr', 'create', '--head', branch, '--title', `Bulwark: resilience fixes for ${summary.target}`, '--body-file', summary.artifacts.pr], { encoding: 'utf8' });
452	  if (res.status !== 0) throw new Error(`gh pr create failed: ${res.stderr.trim()}`);
453	  return res.stdout.trim();
454	}
