494	function print(e: LoopEvent) {
495	  switch (e.type) {
496	    case 'run-start':
497	      return console.log(c.bold(`Bulwark loop → ${e.target}`) + c.dim(` | fixer ${e.fixer} | red ${e.redTrials} trials, judge ${e.judgeTrials} trials | run ${e.runId}\n`));
498	    case 'analyze':
499	      console.log(c.red('RED') + ` found ${e.findings.length} weak links:`);
500	      for (const f of e.findings) {
501	        console.log(`  ${f.severity === 'high' ? c.red('high') : c.yellow('med ')}  ${f.file}:${f.line}  ${f.why}`);
502	        if (f.blast) console.log(c.dim(`        blast radius (Entire Graph): ${describeBlast(f.blast)}`));
503	      }
504	      for (const line of summarizeProvenance(e.provenance ?? [])) console.log(c.dim(`  provenance: ${line}`));
505	      return console.log();
506	    case 'scorecard': {
507	      if (e.phase === 'after') allPassAfter = e.results.every((r) => r.passed === r.trials);
508	      const label = e.phase === 'before' ? c.red('RED') + ' scorecard (before)' : c.bold('Scorecard after fixes');
509	      console.log(`${label}: overall ${pct(e.overall)} of trials kept every rule`);
510	      for (const r of e.results) {
511	        const risk = r.dollarsAtRisk ? c.dim(`  ${money(r.dollarsAtRisk.per1kTickets)} at risk / 1k tickets`) : '';
512	        console.log(`  ${r.fault.padEnd(22)} ${(r.passed === r.trials ? c.green : c.red)(`${r.passed}/${r.trials}`.padEnd(6))}${risk}`);
513	      }
514	      return console.log();
515	    }
516	    case 'fault-start':
517	      return console.log(c.bold(`▶ ${e.fault}`) + c.dim(`  ${e.hypothesis}`));
518	    case 'observe': {
519	      const tag = e.status === 'read' ? c.green('read') : e.status === 'pending' ? c.yellow('pending') : c.dim('unavailable');
520	      return console.log(`  ${c.dim('OBSERVE')} neatlogs ${tag}: ${c.dim(describeObserve(e))}`);
521	    }
522	    case 'fault-skip':
523	      return console.log(c.dim(`  skipped: ${e.reason}`));
524	    case 'checkpoint':
525	      return console.log(c.dim(`  ${e.action === 'save' ? '⎘ checkpoint' : '↺ rolled back to'} ${e.id}`));
526	    case 'slo-plan':
527	      console.log(c.bold(`SLO plan`) + c.dim(` (${fmtRate(e.confidence)} confidence, ${e.method})`));
528	      for (const p of e.plans) console.log(`  ${describePlan(p)}`);
529	      return console.log();
530	    case 'attempt':
531	      return console.log(`  ${c.blue('BLUE')} ${e.round ? `round ${e.round} candidate` : 'attempt'} ${e.n}: ${e.title} ${c.dim(`(${e.strategy}, ${e.author}, +${e.added}/-${e.removed})`)}`);
532	    case 'verdict': {
533	      const tag =
534	        e.status === 'fixed' ? (fixedWithOverhead(e) ? c.yellow('FIXED WITH OVERHEAD') : c.green('FIXED')) : e.status === 'inconclusive' ? c.yellow('INCONCLUSIVE') : c.red('REJECTED');
535	      console.log(`  ${c.yellow('JUDGE')} ${tag} ${e.reasons.join('; ')}`);
536	      if (e.overhead) console.log(c.dim(`        overhead: ${describeOverhead(e.overhead)}`));
537	      return;
538	    }
539	    case 'tournament': {
540	      console.log(`  ${c.bold('TOURNAMENT')} round ${e.round}: ${e.winner ? c.green(`${e.winner} wins`) : c.red('no winner')}`);
541	      for (const r of e.ranking) console.log(`    ${r.rank}. ${r.entrant.padEnd(18)} ${(r.strategy ?? '—').padEnd(26)} ${r.outcome === 'winner' ? c.green(r.outcome) : c.dim(r.outcome)}: ${r.reason}`);
542	      return;
543	    }
544	    case 'mutation':
545	      return console.log(`  ${c.dim('GUARD')} regression test without fix ${e.unfixedPassed}/${e.trials}, with fix ${e.fixedPassed}/${e.trials} ${e.ok ? c.green('✓ proven') : c.red('✗ not proven')}`);
546	    case 'fault-done':
547	      return console.log();
548	    case 'residual':
549	      if (e.findings.length === 0) return console.log(c.green('No weak links remain in the final code.\n'));
550	      console.log(c.yellow(`Remaining risk (${e.findings.length}):`) + (allPassAfter ? ' every attack passes, but the analyzer still sees:' : ' the analyzer still sees:'));
551	      for (const f of e.findings) console.log(`  ${f.file}:${f.line}  ${f.why}`);
552	      return console.log();
553	    case 'log':
554	      return console.log(c.dim(`  ${e.message}`));
555	    case 'run-done': {
556	      const s = e.summary;
557	      console.log(c.bold(`Resilience ${pct(s.overallBefore)} → ${pct(s.overallAfter)}`) + `  fixed ${s.fixed.length}, unfixed ${s.unfixed.length}, skipped ${s.skipped.length} · ${s.attempts} attempts, ${s.rollbacks} rollbacks`);
558	      if (s.cost) {
559	        const k = s.cost;
560	        console.log(`Run cost ${c.bold(usd(k.totalUsd))}` + c.dim(` = LLM ${usd(k.llmUsd)} (${k.calls} calls, ${k.inputTokens + k.outputTokens} tokens) + compute ${usd(k.computeUsd)} (${Math.round(k.wallMs / 1000)}s) · ${k.trials} trials`));
561	      }
562	      return console.log(c.dim(`Artifacts: ${s.dir}/ (fix.patch, PR.md, postmortem-*.md, badge.svg, summary.json)`));
563	    }
564	  }
565	}
