      ...base,
      traceId: c.traceId,
      seed: c.seed,
      source: c.source,
      status: res.status,
      waitedMs: Date.now() - started,
      ...(res.reason ? { reason: res.reason } : {}),
      ...(res.stage ? { stage: res.stage } : {}),
