/** A cached LLM-compiled rule for this target and exact rule text: the local cache first, then the target's lockfile. */
export function lookupCompiled(target: string, rule: string, paths = [CACHE_PATH, lockfilePath(target)]): LlmCompiledRule | undefined {
  const key = cacheKey(target, rule);
  for (const p of paths) {
    if (!existsSync(p)) continue;
    const hit = readCache(p).rules[key];
    if (hit && hit.rule === rule && hit.dslVersion === DSL_VERSION) return hit;
  }
  return undefined;
}

